local ThermometerMaker = {}
local PRODUCTS = {
    glass_thermometer = { name = "Stekleni termometer", glassCost = 2, mercuryCost = 1, time = 3, cost = 40, accuracy = 50, prestige = 3, description = "Stekleni termometer z živim srebrom." },
    brass_thermometer = { name = "Medeninast termometer", glassCost = 1, mercuryCost = 1, brassCost = 1, time = 4, cost = 80, accuracy = 65, prestige = 5, happiness = 1, description = "Medeninast termometer za učenjake." },
    silver_thermometer = { name = "Srebrn termometer", glassCost = 1, mercuryCost = 1, silverCost = 1, time = 6, cost = 180, accuracy = 78, prestige = 9, happiness = 2, description = "Srebrn termometer za zdravnike." },
    silver_scale_thermometer = { name = "Srebrnolestvni termometer", glassCost = 1, mercuryCost = 1, silverCost = 1, goldCost = 1, time = 9, cost = 420, accuracy = 88, prestige = 15, happiness = 3, description = "Termometer s srebrno lestvico za plemiče." },
    gold_case_thermometer = { name = "Zlatookvirni termometer", glassCost = 1, mercuryCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, time = 12, cost = 900, accuracy = 94, prestige = 25, happiness = 5, description = "Termometer z zlatim okvirjem za visoke plemiče." },
    royal_grand_thermometer = { name = "Kraljevski veliki termometer", glassCost = 2, mercuryCost = 1, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, time = 17, cost = 2000, accuracy = 100, prestige = 45, happiness = 9, description = "Veliki kraljevski termometer z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Termometerska delavnica", cost = { gold = 320, wood = 130, stone = 250 }, upkeep = 8, qualityBonus = 5 },
    glass_tube_room = { name = "Steklenocevna soba", cost = { gold = 1100, wood = 280, stone = 500, glass = 8 }, upkeep = 28, qualityBonus = 18 },
    calibration_room = { name = "Kalibrirnica", cost = { gold = 2600, wood = 400, stone = 800, silver = 40, mercury = 8 }, upkeep = 65, qualityBonus = 30 },
    royal_thermometer_atelier = { name = "Kraljevski atelje termometrov", cost = { gold = 11000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
ThermometerMaker.glassStock = 12; ThermometerMaker.mercuryStock = 14; ThermometerMaker.brassStock = 10; ThermometerMaker.silverStock = 8; ThermometerMaker.goldStock = 6; ThermometerMaker.jewelStock = 6; ThermometerMaker.pearlStock = 4
ThermometerMaker.productStock = {}; ThermometerMaker.buildings = {}; ThermometerMaker.maker = nil; ThermometerMaker.activeMaking = {}; ThermometerMaker.totalProducts = 0; ThermometerMaker.dayTimer = 0
function ThermometerMaker.init() ThermometerMaker.glassStock=12; ThermometerMaker.mercuryStock=14; ThermometerMaker.brassStock=10; ThermometerMaker.silverStock=8; ThermometerMaker.goldStock=6; ThermometerMaker.jewelStock=6; ThermometerMaker.pearlStock=4; ThermometerMaker.productStock={}; ThermometerMaker.buildings={}; ThermometerMaker.maker=nil; ThermometerMaker.activeMaking={}; ThermometerMaker.totalProducts=0; ThermometerMaker.dayTimer=0; print("[ThermometerMaker] Royal Thermometer Maker System initialized (6 products, 4 buildings)") end
function ThermometerMaker.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ThermometerMaker.maker={name=n or ("Termometrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Termometrar najet: %s (spretnost: %d)",ThermometerMaker.maker.name,s),"success") end; return true end
function ThermometerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ThermometerMaker.build(id) local ok,e=ThermometerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ThermometerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ThermometerMaker.getQualityBonus() local b=0; for _,bd in ipairs(ThermometerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ThermometerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and ThermometerMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.mercuryCost and ThermometerMaker.mercuryStock<(d.mercuryCost or 0) then return false,"Premalo živega srebra" end; if d.brassCost and ThermometerMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ThermometerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ThermometerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ThermometerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ThermometerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ThermometerMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ThermometerMaker.maker then return false,"Potreben termometrar" end; return true end
function ThermometerMaker.make(pt,qty) qty=qty or 1; local ok,e=ThermometerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then ThermometerMaker.glassStock=ThermometerMaker.glassStock-d.glassCost*qty end; if d.mercuryCost then ThermometerMaker.mercuryStock=ThermometerMaker.mercuryStock-d.mercuryCost*qty end; if d.brassCost then ThermometerMaker.brassStock=ThermometerMaker.brassStock-d.brassCost*qty end; if d.silverCost then ThermometerMaker.silverStock=ThermometerMaker.silverStock-d.silverCost*qty end; if d.goldCost then ThermometerMaker.goldStock=ThermometerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ThermometerMaker.jewelStock=ThermometerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ThermometerMaker.pearlStock=ThermometerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ThermometerMaker.maker then t=math.max(1,t-math.floor(ThermometerMaker.maker.skill/12)) end; table.insert(ThermometerMaker.activeMaking,{id="thermometer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ThermometerMaker.completeMaking(m) local q=1.0+(ThermometerMaker.getQualityBonus()/100); if ThermometerMaker.maker then q=q+(ThermometerMaker.maker.skill/180) end; q=math.min(2.0,q); ThermometerMaker.productStock[m.productType]=(ThermometerMaker.productStock[m.productType] or 0)+m.quantity; ThermometerMaker.totalProducts=ThermometerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ThermometerMaker.maker then ThermometerMaker.maker.itemsMade=ThermometerMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ThermometerMaker.maker.skill=math.min(100,ThermometerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Termometer izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"thermometer.completed",{productName=m.productName,accuracy=m.accuracy,prestige=m.prestige,happiness=m.happiness}) end end
function ThermometerMaker.update(dt) if not _G.state then return end; ThermometerMaker.dayTimer=ThermometerMaker.dayTimer+dt; if ThermometerMaker.dayTimer>=30 then ThermometerMaker.dayTimer=0; for i=#ThermometerMaker.activeMaking,1,-1 do local m=ThermometerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ThermometerMaker.completeMaking(m); table.remove(ThermometerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ThermometerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ThermometerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ThermometerMaker.getStats() return {glassStock=ThermometerMaker.glassStock,mercuryStock=ThermometerMaker.mercuryStock,brassStock=ThermometerMaker.brassStock,silverStock=ThermometerMaker.silverStock,goldStock=ThermometerMaker.goldStock,jewelStock=ThermometerMaker.jewelStock,pearlStock=ThermometerMaker.pearlStock,productStock=ThermometerMaker.productStock,numBuildings=#ThermometerMaker.buildings,hasMaker=ThermometerMaker.maker~=nil,makerName=ThermometerMaker.maker and ThermometerMaker.maker.name or "—",makerSkill=ThermometerMaker.maker and ThermometerMaker.maker.skill or 0,activeMaking=#ThermometerMaker.activeMaking,totalProducts=ThermometerMaker.totalProducts} end
return ThermometerMaker
